function escreverBinario(caminho, base64, descricao) {
  const bufferNovo = Buffer.from(base64, "base64");

  if (existsSync(caminho)) {
    const atual = readFileSync(caminho);
    if (atual.equals(bufferNovo)) {
      jaEstava += 1;
      console.log("  [pulou] " + descricao + " (ja estava aplicada)");
      return;
    }
  }

  writeFileSync(caminho, bufferNovo);
  mudou += 1;
  console.log("  [ok]    " + descricao);
}

escreverBinario("app/favicon.ico", FAVICON_B64, "favicon.ico atualizado com o simbolo do Studio Realcar");
escreverBinario("app/icon.png", ICON_B64, "app/icon.png criado (icone moderno)");

// ---- 2) arquivos sem uso ----
const arquivosMortos = [
  "app/(app)/agenda/components/AgendaHeader.tsx",
  "app/(app)/agenda/components/EventoCard.tsx",
  "components/clientes/ClienteCards.tsx",
  "lib/lancamento.ts",
  "lib/ux.ts",
];

for (const caminho of arquivosMortos) {
  if (!existsSync(caminho)) {
    jaEstava += 1;
    console.log("  [pulou] remove " + caminho + " (ja não existe)");
    continue;
  }

  rmSync(caminho);
  mudou += 1;
  console.log("  [ok]    remove " + caminho);
}

console.log(
  "\nPronto! " +
    mudou +
    " alteracao(oes) aplicada(s)" +
    (jaEstava > 0 ? ", " + jaEstava + " ja estava(m) no lugar" : "") +
    ".\n",
);
console.log("Agora rode:  npm run build\n");
